-- Franchise burgers with their set fries and soft drinks (#31), from each brand's official Korean
-- nutrition information, checked on 2026-11-08. Sources and the menus left out are listed in
-- docs/changes/31-franchise-foods.md. The brands publish saturated fat, not total fat, and no
-- carbohydrates, so fat and carbs stay NULL (not known). Franchise fast food is junk food (#38);
-- the mark is set only when a food is first added, so a mark the user changed stays.
ON CONFLICT (name, COALESCE(brand, '')) DO UPDATE SET
  category = EXCLUDED.category,
  serving_size = EXCLUDED.serving_size,
  serving_unit = EXCLUDED.serving_unit,
  calories = EXCLUDED.calories,
  carbs = EXCLUDED.carbs,
  protein = EXCLUDED.protein,
  fat = EXCLUDED.fat,
  sugars = EXCLUDED.sugars,
  sodium = EXCLUDED.sodium,
  source_type = EXCLUDED.source_type,
  source_url = EXCLUDED.source_url,
  checked_on = EXCLUDED.checked_on,
  updated_at = now()
WHERE EXCLUDED.checked_on > foods.checked_on;
